using System;

// PROGRAM: Eksperimen Short-Circuit Evaluation dan Hukum De Morgan
bool CekKoneksiDatabase()
{
    Console.WriteLine("[LOG] Memeriksa koneksi database... (Operasi Mahal)");
    return true;
}

bool isCacheValid = false;

Console.WriteLine("=== UJI 1: Short-Circuit (||) ===");
// Karena isCacheValid bernilai FALSE, sisi kanan WAJIB dievaluasi
if (isCacheValid || CekKoneksiDatabase())
{
    Console.WriteLine("Hasil: Data berhasil diambil.");
}

Console.WriteLine("\n=== UJI 2: Short-Circuit saat Kiri TRUE ===");
isCacheValid = true;
// Karena sisi kiri bernilai TRUE, method CekKoneksiDatabase() TIDAK AKAN DIPANGGIL sama sekali!
if (isCacheValid || CekKoneksiDatabase())
{
    Console.WriteLine("Hasil: Data diambil instan dari cache!");
}

