using System;

public class LoanApprovalEngine
{
    public static bool IsLoanApproved(int age, decimal monthlyIncome, bool hasBadCredit, bool isPriorityCustomer)
    {
        if (age < 21) return false;
        if (hasBadCredit) return false;

        decimal minIncome = isPriorityCustomer ? 3_000_000m : 5_000_000m;
        return monthlyIncome >= minIncome;
    }

    public static void Main()
    {
        Console.WriteLine(IsLoanApproved(25, 6000000, false, false));
        Console.WriteLine(IsLoanApproved(22, 4000000, false, true));
        Console.WriteLine(IsLoanApproved(30, 10000000, true, false));
    }
}
